$p='Assets/Scripts/PauseMenu.cs';$s=Get-Content $p -Raw
$a=$s.IndexOf(' void Toggle(');$b=$s.IndexOf(' void Build()',$a)
$replacement=' void Toggle(Transform parent,string label,bool value,UnityEngine.Events.UnityAction<bool> changed){var r=Rect(label,parent,new Vector2(580,48));var icon=GridShiftUITheme.Art(r,"Toggle_Desligado",new Vector2(80,38),new Vector2(265,0));var toggle=r.gameObject.AddComponent<Toggle>();toggle.targetGraphic=icon;toggle.transition=Selectable.Transition.None;toggle.SetIsOnWithoutNotify(value);var text=Text(r,label,20);text.rectTransform.sizeDelta=new Vector2(440,40);text.rectTransform.anchoredPosition=new Vector2(-60,0);void Refresh(bool on){GridShiftUITheme.Surface(icon,on?"Toggle_Ligado":"Toggle_Desligado",false);icon.raycastTarget=true;}Refresh(value);toggle.onValueChanged.AddListener(v=>{Refresh(v);changed(v);});}'+[Environment]::NewLine
$s=$s.Substring(0,$a)+$replacement+$s.Substring($b)
$s=$s.Replace('new GameObject[5]','new GameObject[6]').Replace('i<5','i<6').Replace('j<5','j<6').Replace('"Desempenho","Controles"','"Desempenho","Controles","Interface"').Replace('Slider(play,"Movimento do HUD"','Slider(pages[5].transform,"Movimento do HUD"')
$s=$s.Replace('for(int j=0;j<6;j++)pages[j].SetActive(j==index);','for(int j=0;j<6;j++)pages[j].SetActive(j==index);foreach(var tab in tabs.GetComponentsInChildren<Button>())GridShiftUITheme.Surface(tab.GetComponent<Image>(),tab.name==names[index]?"Aba_Ativa":"Aba_Inativa");foreach(var tab in tabs.GetComponentsInChildren<Button>())tab.GetComponent<Image>().raycastTarget=true;')
$s=$s.Replace('panel.sizeDelta=new Vector2(show?1100:680,show?900:620);','panel.sizeDelta=new Vector2(show?1100:680,show?900:650);GridShiftUITheme.Surface(panel.GetComponent<Image>(),show?"Painel_Configuracoes_Escuro":"Painel_Menu_Cantos_Amarelos");')
Set-Content $p $s
